import os
import zipfile
import xml.etree.ElementTree as ET

NS = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
ET.register_namespace("", NS)

path = "sales_data.xlsx"
zin = zipfile.ZipFile(path)
entries = {n: zin.read(n) for n in zin.namelist()}
zin.close()

root = ET.fromstring(entries["xl/worksheets/sheet1.xml"])
sheetdata = root.find(f"{{{NS}}}sheetData")

def num(cell):
    if cell is None:
        return None
    v = cell.find(f"{{{NS}}}v")
    if v is None or v.text in (None, ""):
        return None
    try:
        return float(v.text)
    except ValueError:
        return None

def set_v(cell, val):
    v = cell.find(f"{{{NS}}}v")
    if v is None:
        v = ET.SubElement(cell, f"{{{NS}}}v")
    v.text = "" if val is None else repr(val)

cells_by_row = {}
for row in sheetdata.findall(f"{{{NS}}}row"):
    rn = int(row.get("r"))
    cells = {}
    for c in row.findall(f"{{{NS}}}c"):
        ref = c.get("r")
        cells["".join(ch for ch in ref if ch.isalpha())] = c
    cells_by_row[rn] = cells

computed = {}
for rn in range(2, 10):
    cells = cells_by_row[rn]
    C, D, F = num(cells.get("C")), num(cells.get("D")), num(cells.get("F"))
    E = C * D if (C is not None and D is not None) else None
    G = E - C * F if (E is not None and C is not None and F is not None) else None
    H = G / E if (G is not None and E) else None
    computed[rn] = (C, E, G, H)

Ctot = sum(computed[r][0] for r in computed)
Etot = sum(computed[r][1] for r in computed)
Gtot = sum(computed[r][2] for r in computed)
Htot = Gtot / Etot if Etot else None
computed[10] = (Ctot, Etot, Gtot, Htot)

for rn, (C, E, G, H) in computed.items():
    cells = cells_by_row[rn]
    for col, val in (("E", E), ("G", G), ("H", H)):
        c = cells.get(col)
        if c is not None and c.find(f"{{{NS}}}f") is not None:
            set_v(c, val)
    if rn == 10 and cells.get("C") is not None:
        set_v(cells["C"], C)

tmp = path + ".tmp"
with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zout:
    for n, data in entries.items():
        if n == "xl/worksheets/sheet1.xml":
            data = ET.tostring(root, encoding="utf-8", xml_declaration=True)
        zout.writestr(n, data)
os.replace(tmp, path)

print("Cached values written for E, G, H (rows 2-10) and C10.")
for rn in sorted(computed):
    C, E, G, H = computed[rn]
    print(f"row {rn}: Revenue={E}  Profit={G}  Margin={H}")

